"""Build the private review of the current, concept-first student lesson V6.

Reuses the established Markdown parser and typed-answer mechanics from V3.
Owns the V6 source selection, visual system, diagrams, and objective quizzes.
"""
from pathlib import Path
import importlib.util
import html
import json

HERE = Path(__file__).resolve().parent
RECAP = HERE.parents[1] / 'students/yahunatan-zetvy/recaps/2026-09-16-recap.md'
DRAFT = HERE / 'concept-lesson-v6.md'
OUTPUT = HERE / 'conditional-reasoning-v6.html'
BEGIN = '<!-- BEGIN CURRENT STUDENT LESSON V6 -->'
END = '<!-- END CURRENT STUDENT LESSON V6 -->'

spec = importlib.util.spec_from_file_location('recap_v3_renderer', HERE / 'build-preview-v3.py')
base = importlib.util.module_from_spec(spec)
spec.loader.exec_module(base)


def source_text():
    canonical = RECAP.read_text(encoding='utf-8-sig')
    if BEGIN in canonical or END in canonical:
        if canonical.count(BEGIN) != 1 or canonical.count(END) != 1 or canonical.index(BEGIN) >= canonical.index(END):
            raise ValueError('Current V6 lesson markers must occur once, in order')
        text = canonical.split(BEGIN, 1)[1].split(END, 1)[0].strip()
        origin = 'canonical current student lesson V6 marker block'
    else:
        text = DRAFT.read_text(encoding='utf-8-sig').strip()
        origin = 'concept-lesson-v6.md review draft'
    if any(value in text for value in ['Notes for me', 'teacher_note', '\u2014']):
        raise ValueError('Private notes or prohibited punctuation in student text')
    return text, origin


def quiz(number, question, choices, correct, answer):
    return f'''<section class="pop-quiz" data-quiz="{number}" data-correct="{correct}"><div class="pop-title"><span>Pause and predict</span><span class="quiz-mark" aria-hidden="true">?</span></div><h3>{html.escape(question)}</h3><div class="quiz-choices">'''+''.join(f'<button type="button" data-answer="{i}" aria-pressed="false">{html.escape(choice)}</button>' for i, choice in enumerate(choices))+f'''</div><div class="quiz-feedback" hidden tabindex="-1"><strong class="quiz-verdict"></strong><p>{html.escape(answer)}</p></div></section>'''


class Renderer(base.Renderer):
    def prose(self, block):
        for label in ['Definition', 'Concrete example', 'Given fact', 'Match', 'Therefore', 'Why', 'What follows', 'New conditional']:
            prefix = '**' + label + ':**'
            if block.startswith(prefix):
                kind = 'definition' if label == 'Definition' else 'result' if label in ['Therefore', 'What follows', 'New conditional'] else 'given' if label == 'Given fact' else 'explanation'
                return '<div class="teaching-line teaching-' + kind + '"><span class="teaching-label">' + label + '</span><p>' + base.inline(block[len(prefix):].strip()) + '</p></div>'
        if ' → ' in block and block.startswith('**') and ':**' in block:
            label, value = block.split(':**', 1)
            return '<div class="rule-line"><span class="eyebrow">'+base.inline(label.strip('*'))+'</span>'+base.route(value.strip().rstrip('.').split(' → '))+'</div>'
        if '**Example:**' in block and block.startswith(('**Fact:**', '**Rule:**', '**Conclusion:**')):
            definition, example = block.split('\n**Example:**', 1)
            label, meaning = definition.split(':**', 1)
            name = label.strip('*')
            return '<section class="opening-beat beat-'+name.lower()+'"><h3>'+base.inline(name)+'</h3><p class="beat-definition">'+base.inline(meaning.strip())+'</p><p class="beat-example">'+base.inline(example.strip())+'</p></section>'
        return super().prose(block)


base.FACT_LAB = '''<section class="fact-lab" aria-label="Explore the fact, rule, and result"><div class="lab-top"><h2>Follow the fact.</h2><button type="button" id="replay-flow">Replay the path</button></div><label for="fact-choice">Give the application one fact</label><select id="fact-choice"><option value="late">It was submitted late.</option><option value="notapproval">It does not require special approval.</option><option value="approval">It requires special approval.</option><option value="notlate">It was not submitted late.</option></select><div class="proof-flow" id="proof-flow"><div class="flow-node fact-node"><span>Given fact</span><strong id="proof-given">Submitted late</strong></div><div class="signal-track" aria-hidden="true"></div><div class="flow-node rule-node"><span>Use the rule</span><strong id="proof-rule">Late → Requires approval</strong></div><div class="signal-track second" aria-hidden="true"></div><div class="flow-node result-node"><span>Guaranteed result</span><strong id="proof-result">Requires special approval</strong></div></div><div class="fact-display" aria-live="polite"><span id="fact-move">Apply forward</span><p id="fact-result">It requires special approval.</p><p id="fact-reason">The fact meets the rule's starting condition. The requirement follows.</p></div><p class="lab-foot">Change the given fact. The policy stays the same.</p></section>'''
base.VISUALS['TWO-MOVES'] = '''<figure class="two-moves"><div class="move forward"><span class="move-name">Forward</span><div class="movement"><span class="given">Submitted late</span><span class="moving-arrow" aria-hidden="true">→</span><span class="follows">Requires approval</span></div><p>You have the starting condition. The required result follows.</p></div><div class="move backward"><span class="move-name">Contrapositive</span><div class="movement"><span class="given">Does not require approval</span><span class="moving-arrow" aria-hidden="true">→</span><span class="follows">Not submitted late</span></div><p>The required result is absent. The starting condition is ruled out.</p></div><figcaption>Reverse the direction. Negate both complete ideas. Preserve the rule.</figcaption></figure>'''
base.VISUALS['SHARED-TRIGGER'] = '''<figure class="fork"><div class="fork-root"><small>The shared trigger</small><strong>Submitted late</strong></div><svg viewBox="0 0 600 90" role="img" aria-label="Two separate arrows lead from submitted late to two requirements"><path d="M300 3V28Q300 45 275 45H120V78M300 28Q300 45 325 45H480V78" fill="none" stroke="currentColor" stroke-width="3"/><path d="M113 68L120 80L127 68M473 68L480 80L487 68" fill="none" stroke="currentColor" stroke-width="3"/></svg><div class="fork-results"><span>Requires approval</span><span>Needs a signature</span></div><div class="missing-link"><span aria-hidden="true">↔</span> No connection between these results is given.</div><figcaption>A late application has both requirements. An application needing approval could be on time and not need a signature.</figcaption></figure>'''
base.VISUALS['POP-QUIZ-1'] = quiz(1, 'The application requires approval. Was it late?', ['It must have been late.', 'It could have been late. We cannot tell.', 'It could not have been late.'], 1, 'The middle answer is correct. An on-time application could require approval for another reason. Both a late application requiring approval and an on-time application requiring approval fit the rule.')
base.VISUALS['POP-QUIZ-2'] = quiz(2, 'Late applications need approval and a signature. What does approval alone prove?', ['The application was late.', 'The application needs a signature.', 'Neither conclusion is guaranteed.'], 2, 'Neither is guaranteed. An on-time application could require approval without needing a signature. Both original rules still hold because neither is triggered by that application.')

base.FACT_LAB = base.FACT_LAB.replace('<label for="fact-choice">Give the application one fact</label>', '<fieldset class="fact-picks"><legend>Give the application one fact</legend><button type="button" data-fact="late" aria-pressed="true">Submitted late</button><button type="button" data-fact="notapproval" aria-pressed="false">Approval not required</button><button type="button" data-fact="approval" aria-pressed="false">Approval required</button><button type="button" data-fact="notlate" aria-pressed="false">Not submitted late</button></fieldset><details class="alternate-control"><summary>Choose from a list</summary><label for="fact-choice">Given fact</label>').replace('</select><div class="proof-flow"', '</select></details><div class="proof-flow"')
base.VISUALS['FACT-LAB'] = base.FACT_LAB
base.FACT_LAB = '''<figure class="inference-overview"><div><span>Given information</span><strong>Read each whole idea.</strong></div><span class="overview-arrow" aria-hidden="true">↓</span><div><span>Supported move</span><strong>Find what the statements guarantee.</strong></div><span class="overview-arrow" aria-hidden="true">↓</span><div><span>Conclusion</span><strong>Keep only what must follow.</strong></div><figcaption>Inference means proving a new claim from the information you are given.</figcaption></figure>'''
base.VISUALS['FACT-SCOPE'] = '''<figure class="fact-scope"><div><span>One identified case</span><strong>Application J<br>was late.</strong><p>J's submission time is given. Other applications are not described.</p></div><div><span>At least one case</span><strong>Some applications<br>were late.</strong><p>A late application exists. The statement does not say all were late.</p></div><figcaption>A fact's scope tells you how much is established before you infer anything else.</figcaption></figure>'''
base.VISUALS['RULE-PARTS'] = '''<figure class="rule-parts"><div><span>Condition</span><strong>Submitted after<br>the deadline</strong></div><span class="thick-arrow" aria-label="requires">→</span><div><span>Required result</span><strong>Requires<br>special approval</strong></div><figcaption>If the condition is met, the result is required. The arrow does not work backward by itself.</figcaption></figure>'''

