base.VISUALS['FACT-SCOPE'] = '''<figure class="fact-scope"><div><span>One identified case</span><strong>Mira<br>is trained.</strong><p>Training is established for Mira. Other people's training is not described.</p></div><div><span>At least one case</span><strong>Some staff members<br>are trained.</strong><p>At least one trained staff member exists. This does not say every staff member is trained.</p></div><figcaption>Keep the fact's scope: one named case, at least one case, or whatever the statement actually establishes.</figcaption></figure>'''
base.VISUALS['RULE-PARTS'] = '''<figure class="rule-parts"><div><span>Starting condition</span><strong>Is trained</strong></div><span class="thick-arrow" aria-hidden="true">→</span><div><span>Required result</span><strong>Has a badge</strong></div><figcaption>Every trained person has a badge. This rule connects conditions without establishing that a trained person exists.</figcaption></figure>'''
base.VISUALS['TWO-MOVES'] = '''<figure class="two-moves"><div class="move forward"><span class="move-name">Apply forward</span><div class="movement"><span class="given">Is trained</span><span class="moving-arrow" aria-hidden="true">→</span><span class="follows">Has a badge</span></div><p>A fact establishes the starting condition for this person.</p></div><div class="move backward"><span class="move-name">Apply the contrapositive</span><div class="movement"><span class="given">No badge</span><span class="moving-arrow" aria-hidden="true">→</span><span class="follows">Not trained</span></div><p>A fact denies the required result for this person.</p></div><figcaption>The original rule and its contrapositive support the same relationship. Keep the same person throughout the inference.</figcaption></figure>'''
base.VISUALS['APPLY-SEQUENCE'] = '''<figure class="application-proof"><span class="teaching-label">One rule applied to one case</span><div class="route"><span class="node">Mira is trained</span><span class="arrow" aria-hidden="true">→</span><span class="node">Mira has a badge</span></div><figcaption>The case fact meets “is trained.” The rule guarantees “has a badge” for that same case.</figcaption></figure>'''
base.VISUALS['TWO-OUTPUTS'] = '''<figure class="output-comparison"><div><span class="teaching-label">Rules alone</span><strong>Late → Needs a signature</strong><p>A general conditional connection.<br>No late application is established.</p></div><div><span class="teaching-label">Rules + J's fact</span><strong>J needs a signature.</strong><p>A conclusion about J.<br>J's lateness activates the chain.</p></div><figcaption>Linking creates a rule. Applying uses a fact to establish its result in a case.</figcaption></figure>'''
base.VISUALS['HIDDEN-CHAIN'] = '''<figure class="hidden-chain"><span class="teaching-label">Reveal the middle</span><div class="route"><span class="node">No badge</span><span class="arrow" aria-hidden="true">→</span><span class="node">Not trained</span><span class="arrow" aria-hidden="true">→</span><span class="node">Requires supervision</span></div><figcaption>Contrapose Trained → Has a badge. Its result now matches the starting condition of Not trained → Requires supervision.</figcaption></figure>'''
