def main():
    text, origin = source_text()
    renderer = Renderer()
    title, body = renderer.render(text)
    body = body.replace('<a href="#section-2">Contrapositives</a>', '<a href="#section-2">Rules</a>').replace('<a href="#section-3">Linking</a>', '<a href="#section-3">Applying</a>').replace('<a href="#section-5">Whole ideas</a>', '<a href="#section-4">Negating</a><a href="#section-5">Linking</a>')
    if renderer.checks != 7 or len(renderer.practice) != 4:
        raise ValueError('V6 must retain seven typed checks and four mixed problems')
    data = json.dumps(renderer.practice, ensure_ascii=False).replace('<', '\\u003c')
    hero_title = '<h1 class="lesson-title"><span>Facts,</span><span>Rules,</span><span>and What Follows</span></h1>'
    body = '<section class="hero">'+hero_title+body.replace('</header>', '</header></section>', 1)
    page = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="lsatu-interactive-lesson" content="yahunatan-2026-09-16-conditional-reasoning"><title>{html.escape(title)} | LSAT U</title><style>{CSS}{HERO_CSS}{READING_CSS}{V6_CSS}</style></head><body><header class="top"><b>LSAT U</b><div class="top-right"><span>Notes and recaps</span><button type="button" id="motion-toggle" aria-pressed="false">Pause motion</button></div></header><main class="lesson-shell">{body}<footer>Start with what is given. Keep the whole idea. Follow the direction the rule supports.</footer></main><script>const practice={data};{base.JS}{EXTRA_JS}</script></body></html>'''
    if len(page.encode('utf-8')) >= 500_000 or 'concept lesson' in page.lower() or '\u2014' in page:
        raise ValueError('Student package violates size, wording, or punctuation requirements')
    OUTPUT.write_text(page, encoding='utf-8')
    print(f'{OUTPUT}\nSource: {origin}\nTyped checks: {renderer.checks}; pop quizzes: 2; mixed practice: {len(renderer.practice)}; bytes: {len(page.encode("utf-8"))}')


if __name__ == '__main__':
    main()
